import backend, reconcile
class Directory:
    def __init__(self):
        self.calls = []
    def get_user(self, user, refresh=False):
        self.calls.append([user, refresh])
        if not refresh:
            raise backend.NotFound(user, authoritative=False)
        if user == 'ash':
            return {}
        if user == 'birch':
            raise backend.Unavailable(user)
        raise backend.NotFound(user)
c = Directory()
result = [reconcile.reconcile(c, ['ash','birch','cedar']), c.calls]
